const web = $('Webhook').first().json || {};
const b = (web.body && typeof web.body === 'object') ? web.body : web;
const pick = (...keys) => {
  for (const k of keys) {
    const v = b[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return undefined;
};
const question = pick('question', 'prompt', 'message', 'query', 'chatInput', 'input');
const expectedAnswer = pick('expectedAnswer', 'expected_answer', 'correctAnswer', 'modelAnswer');
const studentAnswer = pick('userAnswer', 'studentAnswer', 'student_answer', 'answer');
const totalRaw = pick('totalMarks', 'total_marks', 'maxMarks');
const stored = $input.first() ? ($input.first().json || {}) : {};
const fromBody = (typeof b.pdfText === 'string') ? b.pdfText.trim() : '';
const fromStore = (typeof stored.pdf_text === 'string') ? stored.pdf_text.trim() : '';
const pdfText = (fromBody || fromStore).slice(0, 20000);
const out = { valid: true, mode: 'generate', question, expectedAnswer, studentAnswer, totalMarks: undefined, error: '', prompt: '', usesPdf: false };
const gradingFields = { expectedAnswer, studentAnswer, totalMarks: totalRaw };
const present = Object.keys(gradingFields).filter((k) => gradingFields[k] !== undefined);
if (question === undefined) {
  out.valid = false;
  out.error = 'Missing required field: question';
} else if (present.length === 0) {
  const q = String(question);
  const mentionsPdf = /\b(pdf|uploaded|upload|document|file)\b/i.test(q) || fromBody !== '';
  if (!mentionsPdf) {
    out.mode = 'generate';
    out.prompt = 'MODE: GENERATE\nUser request: ' + q;
  } else if (!pdfText) {
    out.valid = false;
    out.error = 'No PDF text is available. Please upload a PDF first, then ask for the assessment again.';
  } else {
    out.mode = 'pdf_assessment';
    out.usesPdf = true;
    let n = 5;
    const m = q.match(/(\d{1,2})\s*(?:[a-z-]+\s+){0,3}(?:questions?|mcqs?|qs?)\b/i) || q.match(/\b(\d{1,2})\b/);
    if (m) {
      const parsed = parseInt(m[1], 10);
      if (parsed >= 1) n = Math.min(parsed, 20);
    }
    let answers = [];
    const sa = b.studentAnswers;
    if (Array.isArray(sa)) {
      answers = sa.map((x) => (x && typeof x === 'object') ? String(x.answer !== undefined ? x.answer : (x.studentAnswer !== undefined ? x.studentAnswer : '')) : String(x === null || x === undefined ? '' : x));
    } else if (sa && typeof sa === 'object') {
      answers = Object.keys(sa).sort((x, y) => Number(x) - Number(y)).map((k) => String(sa[k]));
    }
    answers = answers.map((x) => x.trim());
    const hasAnswers = answers.some((x) => x !== '');
    out.numQuestions = n;
    out.studentAnswers = answers;
    out.hasStudentAnswers = hasAnswers;
    out.prompt = 'MODE: PDF_ASSESSMENT\n'
      + 'Use ONLY the PDF text below. Do not use outside knowledge.\n\nPDF TEXT:\n' + pdfText + '\n\n'
      + 'REQUEST: ' + q + '\n\n'
      + 'Create exactly ' + n + ' assessment questions from the PDF text. '
      + 'For each give: question, expected_answer (taken from the PDF), marks (integer 1 to 5 based on depth), student_answer, marks_awarded, feedback.\n'
      + (hasAnswers
        ? 'Student answers by question number (empty means not answered): ' + JSON.stringify(answers) + '\nCopy each into student_answer, then grade it against expected_answer: marks_awarded is an integer from 0 to marks, and feedback is one short sentence.'
        : 'No student answers were provided: set student_answer to "", marks_awarded to null and feedback to "".')
      + '\nReturn ONLY valid JSON, no markdown, in this shape: {"questions":[{"question":"","expected_answer":"","marks":1,"student_answer":"","marks_awarded":null,"feedback":""}]}';
  }
} else {
  out.mode = 'grade';
  const missing = Object.keys(gradingFields).filter((k) => gradingFields[k] === undefined);
  const total = Number(totalRaw);
  if (missing.length > 0) {
    out.valid = false;
    out.error = 'Missing required grading field(s): ' + missing.join(', ');
  } else if (!isFinite(total) || total <= 0) {
    out.valid = false;
    out.error = 'totalMarks must be a positive number, received: ' + String(totalRaw);
  } else {
    out.totalMarks = total;
    out.prompt = 'MODE: GRADE\nQuestion: ' + String(question) + '\nExpected Answer: ' + String(expectedAnswer) + '\nStudent Answer: ' + String(studentAnswer) + '\nTotal Marks: ' + total;
  }
}
return [{ json: out }];

const prep = $('Prepare Input').first().json;
const raw = $input.first().json.output;
const text = (typeof raw === 'string') ? raw : JSON.stringify(raw === undefined ? '' : raw);
if (!text || text.trim() === '') {
  return [{ json: { success: false, error: 'The AI model returned an empty response', mode: prep.mode, question: prep.question } }];
}
if (prep.mode === 'pdf_assessment') {
  let data = null;
  try {
    const cleaned = text.replace(/```json|```/gi, '');
    const s = cleaned.indexOf('{');
    const e = cleaned.lastIndexOf('}');
    data = JSON.parse(cleaned.slice(s, e + 1));
  } catch (err) {
    data = null;
  }
  const list = data && Array.isArray(data.questions) ? data.questions : [];
  const items = [];
  list.forEach((q) => {
    const qt = q && q.question ? String(q.question).trim() : '';
    const ea = q && q.expected_answer ? String(q.expected_answer).trim() : '';
    if (!qt || !ea) return;
    let marks = Number(q.marks);
    if (!isFinite(marks) || marks <= 0) marks = 1;
    const idx = items.length;
    const given = (prep.studentAnswers && prep.studentAnswers[idx]) ? String(prep.studentAnswers[idx]) : '';
    let awarded = null;
    if (prep.hasStudentAnswers) {
      awarded = Number(q.marks_awarded);
      if (!isFinite(awarded) || awarded < 0) awarded = 0;
      if (awarded > marks) awarded = marks;
      if (given === '') awarded = 0;
    }
    items.push({ number: idx + 1, question: qt, expectedAnswer: ea, studentAnswer: given, marks, marksAwarded: awarded, feedback: (prep.hasStudentAnswers && q.feedback) ? String(q.feedback) : '' });
  });
  if (items.length === 0) {
    return [{ json: { success: false, error: 'Could not generate assessment questions from the PDF text. Please try again.', mode: prep.mode, question: prep.question } }];
  }
  const totalMarks = items.reduce((a, x) => a + x.marks, 0);
  const finalScore = prep.hasStudentAnswers ? items.reduce((a, x) => a + (x.marksAwarded || 0), 0) : null;
  let lines = [];
  items.forEach((x) => {
    lines.push('Q' + x.number + '. ' + x.question + ' [' + x.marks + ' mark' + (x.marks === 1 ? '' : 's') + ']');
    lines.push('Expected answer: ' + x.expectedAnswer);
    lines.push('Student answer: ' + (x.studentAnswer === '' ? '(not provided)' : x.studentAnswer));
    if (prep.hasStudentAnswers) lines.push('Marks awarded: ' + x.marksAwarded + ' / ' + x.marks + (x.feedback ? ' - ' + x.feedback : ''));
    lines.push('');
  });
  lines.push('Total marks: ' + totalMarks);
  if (finalScore !== null) lines.push('Final score: ' + finalScore + ' / ' + totalMarks);
  const readable = lines.join('\n');
  return [{ json: { success: true, mode: prep.mode, question: prep.question, totalQuestions: items.length, totalMarks, finalScore, questions: items, answer: readable, output: readable } }];
}
const result = { success: true, mode: prep.mode, question: prep.question, answer: text, output: text };
if (prep.mode === 'grade') {
  result.expectedAnswer = prep.expectedAnswer;
  result.studentAnswer = prep.studentAnswer;
  result.totalMarks = prep.totalMarks;
  const m = text.match(/Score:?[*\s]*([0-9]+(?:[.][0-9]+)?)\s*\/\s*([0-9]+(?:[.][0-9]+)?)/i);
  if (m) {
    const awarded = Number(m[1]);
    result.marksAwarded = awarded;
    result.feedback = text;
    if (awarded > prep.totalMarks) { result.marksAwarded = prep.totalMarks; result.warning = 'Model awarded more than total marks; capped.'; }
  } else {
    result.marksAwarded = null;
    result.feedback = text;
    result.warning = 'Could not read a Score line from the model response';
  }
}
return [{ json: result }];
